--
-- Table structure for table `order_print_logs`
--

DROP TABLE IF EXISTS `order_print_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `order_print_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) unsigned NOT NULL,
  `order_item_id` bigint(20) unsigned DEFAULT NULL,
  `store_id` bigint(20) unsigned DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `order_number` varchar(64) DEFAULT NULL,
  `printed_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `printer_name` varchar(160) NOT NULL,
  `tray_key` varchar(120) DEFAULT NULL,
  `tray_label` varchar(160) DEFAULT NULL,
  `is_default_printer` tinyint(1) NOT NULL DEFAULT 0,
  `copies` smallint(5) unsigned NOT NULL DEFAULT 1,
  `size` varchar(20) DEFAULT NULL,
  `media` varchar(40) DEFAULT NULL,
  `gsm` varchar(20) DEFAULT NULL,
  `user_type` tinyint(3) unsigned DEFAULT NULL,
  `pdf_path` varchar(255) DEFAULT NULL,
  `pdf_bytes` bigint(20) unsigned DEFAULT NULL,
  `pdf_sha256` char(64) DEFAULT NULL,
  `status` enum('success','failed','retried') NOT NULL DEFAULT 'success',
  `error_message` text DEFAULT NULL,
  `duration_ms` int(10) unsigned DEFAULT NULL,
  `client_ip` varchar(45) DEFAULT NULL,
  `user_agent` varchar(512) DEFAULT NULL,
  `qz_tray_version` varchar(32) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_print_logs_order_item_id_foreign` (`order_item_id`),
  KEY `order_print_logs_user_id_foreign` (`user_id`),
  KEY `order_print_logs_store_id_printed_at_index` (`store_id`,`printed_at`),
  KEY `order_print_logs_order_id_index` (`order_id`),
  KEY `order_print_logs_printer_name_printed_at_index` (`printer_name`,`printed_at`),
  KEY `order_print_logs_status_index` (`status`),
  CONSTRAINT `order_print_logs_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_print_logs_order_item_id_foreign` FOREIGN KEY (`order_item_id`) REFERENCES `order_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_print_logs_store_id_foreign` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_print_logs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

